PrCssDescriptor cssDescriptorFromText(CssAtRule rule, PrStringView text) {
    uint64_t word;
    uint64_t hash = nameHashLower(text.data, text.size, 0x70296a7173d6f280ull, &word);
    hash = nameMix(hash ^ rule);
    uint32_t descriptor = kCssDescriptorSlot[(uint32_t(hash)
        + kCssDescriptorDisplace[(hash >> 32) & 31u] * (uint32_t(hash >> 32) | 1))
        & 127u];
    if (kCssDescriptorRule[descriptor] != rule
        || !nameEqualsLower(cssDescriptorName(PrCssDescriptor(descriptor)), text, word)) {
        return PrCssDescriptor_None;
    }
    return PrCssDescriptor(descriptor);
}

